    validateDecisions(decisions){
        var period = window.mySimulation.state.currentPeriod;
        if(period === 1){
            decisions.cpDuration   = parseInt(document.getElementById('cpDurationInput').value, 10);
            decisions.floatAvg     = parseInt(document.getElementById('floatAvgInput').value, 10);
            decisions.wbsErrors    = parseInt(document.getElementById('wbsErrorsInput').value, 10);
            decisions.nearCritical = parseInt(document.getElementById('nearCriticalInput').value, 10);
