            feedback  = '<h3>' + this._t('fb_r4_title') + '</h3>';
            feedback += '<p>' + this._t('fb_r4_rec').split('{label}').join(this._recLabel(rec)).split('{t}').join(ds.targetWeek).split('{f}').join(ds.forecastDuration.toFixed(1)).split('{s}').join(alignmentScore) + '</p>';
            feedback += '<p>' + this._t('fb_r4_pen').split('{label}').join(this._penLabel(d.penalty)).split('{s}').join(penScore) + '</p>';
            feedback += '<p>' + this._t('fb_r4_bon').split('{label}').join(this._bonLabel(d.bonus)).split('{s}').join(bonScore) + '</p>';
            feedback += '<p>' + this._t('fb_r4_bank').split('{label}').join(this._bankLabel(d.bank)).split('{s}').join(bankScore) + '</p>';
            feedback += '<p>' + this._t('fb_r4_final').split('{bonus}').join(ds.bonusM).split('{penalty}').join(ds.penaltyM).split('{accel}').join(Math.round(ds.extraCostM)).split('{net}').join(ds.netM).split('{trust}').join(Math.max(0, Math.min(100, ds.ownerTrust + trustDelta))) + '</p>';
            if(rec === 'go' && d.penalty !== 'renegotiate'){
                feedback += '<p>' + this._t('fb_r4_trap') + '</p>';
            }
            if(rec === 'decline' && ds.targetWeek <= 33){
                feedback += '<p>' + this._t('fb_r4_inconsistency') + '</p>';
            }
            feedback += '<p>' + this._t('fb_r4_closing') + '</p>';
        }

        ds.ownerTrust  = Math.max(0, Math.min(100, ds.ownerTrust + trustDelta));
        ds.roundScore  = roundScore;
        ds.cumulativeScore += roundScore;

        ds.durationHistory.push(period === 1 ? 38 : ds.forecastDuration);
        ds.trustHistory.push(ds.ownerTrust);
        ds.extraCostHistory.push(Math.round(ds.extraCostM));
        ds.netHistory.push(ds.netM);
        ds.roundScoreHistory.push(roundScore);

        // Persist the running average score into domainState for the grading/reporting
        // layer (results_utils.php reads domainState.performance.overallScore -> score).
        var _sc = this._avg(ds);
        ds.score = _sc;
        ds.performance = { overallScore: _sc, grade: this._grade(_sc) };

        var fbEl = document.getElementById('feedbackPanel');
        if(fbEl){
            fbEl.innerHTML = feedback;
            fbEl.classList.add('active');
        }

        var self = this;
        setTimeout(((__eqilNext) => function(){
            self._updateBriefing({currentPeriod: __eqilNext});
            self._attachOptionListeners();
        })(state.currentPeriod + 1), 500);

        return {
            period: period,
            forecastDuration: ds.forecastDuration,
            extraCostM: Math.round(ds.extraCostM),
            netM: ds.netM,
            ownerTrust: ds.ownerTrust,
            riskScore: ds.riskScore,
            roundScore: roundScore,
            score: _sc,
            overallScore: _sc
        };
    }

