    _t(key){
        return (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t(key) : key;
    }

    _updateBriefing(state){
        var period = Math.min(state.currentPeriod || 1, this.ROUNDS.length);
        var round = this.ROUNDS[period - 1];
        var briefEl = document.getElementById('briefingText');
        if(briefEl) briefEl.innerHTML = this._t(round.descKey);
        var titleEl = document.getElementById('phaseTitle');
        if(titleEl) titleEl.textContent = this._t(round.titleKey);
        var fbEl = document.getElementById('feedbackPanel');
        if(fbEl && state.currentPeriod === 1){ fbEl.classList.remove('active'); fbEl.innerHTML = ''; }
        for(var i = 1; i <= 4; i++){
            var g = document.getElementById('r' + i + 'Group');
            if(g) g.style.display = (i === period) ? 'block' : 'none';
        }
    }

    _attachOptionListeners(){
        var self = this;
        var checks = document.querySelectorAll('input[name="compOpt"]');
        for(var i = 0; i < checks.length; i++){
            checks[i].onchange = function(){ self._updateR3Preview(); };
        }
        var t = document.getElementById('targetWeekInput');
        if(t) t.onchange = function(){ self._updateR3Preview(); };
    }

    _updateR3Preview(){
        var checks = document.querySelectorAll('input[name="compOpt"]:checked');
        var totalDays = 0, directM = 0, reworkM = 0;
        for(var i = 0; i < checks.length; i++){
            var o = this.OPTIONS[checks[i].value];
            if(!o) continue;
            totalDays += o.daysSaved;
            directM   += o.directM;
            reworkM   += o.reworkM;
        }
        var weeksSaved = totalDays / 7;
        var forecast = Math.max(20, 38 + 8/7 - weeksSaved);
        var t = document.getElementById('targetWeekInput');
        var target = t ? t.value : '';
        var preview = document.getElementById('r3Preview');
        if(!preview) return;
        if(checks.length === 0 && !target){
            preview.classList.remove('active');
            preview.innerHTML = '';
            return;
        }
        var copPerWeek = weeksSaved > 0 ? Math.round((directM + reworkM) / weeksSaved) : 0;
        var html = this._t('preview_title') + '<br>';
        html += this._t('preview_days').split('{d}').join(totalDays).split('{w}').join(weeksSaved.toFixed(1)).split('{f}').join(forecast.toFixed(1)) + '<br>';
        html += this._t('preview_cost').split('{dm}').join(directM).split('{rm}').join(reworkM).split('{tot}').join(directM + reworkM);
        if(weeksSaved > 0) html += this._t('preview_costperweek').split('{c}').join(copPerWeek);
        if(target) html += this._t('preview_target').split('{t}').join(target).split('{status}').join(forecast <= parseFloat(target) + 0.3 ? this._t('preview_ontarget') : this._t('preview_short').split('{d}').join((forecast - parseFloat(target)).toFixed(1)));
        preview.innerHTML = html;
        preview.classList.add('active');
    }

    _scoreClose(answer, target, exactBand, closeBand){
        var d = Math.abs(answer - target);
        if(d <= exactBand) return 25;
        if(d <= closeBand) return 14;
        if(d <= closeBand * 2) return 6;
        return 0;
    }

    _discloseLabel(v){
        if(v === 'separate') return this._t('disclose_res_separate');
        if(v === 'folded')   return this._t('disclose_res_folded');
        return this._t('disclose_res_hide');
    }
    _formworkLabel(v){
        if(v === 'commit')    return this._t('formwork_res_commit');
        if(v === 'negotiate') return this._t('formwork_res_negotiate');
        return this._t('formwork_res_release');
    }
    _recLabel(v){
        if(v === 'go')      return this._t('rec_res_go');
        if(v === 'counter') return this._t('rec_res_counter');
        return this._t('rec_res_decline');
    }
    _penLabel(v){
        if(v === 'renegotiate') return this._t('pen_res_renegotiate');
        if(v === 'accept')      return this._t('pen_res_accept');
        return this._t('pen_res_other');
    }
    _bonLabel(v){
        if(v === 'prorated') return this._t('bon_res_prorated');
        if(v === 'keep')     return this._t('bon_res_keep');
        return this._t('bon_res_drop');
    }
    _bankLabel(v){
        if(v === 'proactive') return this._t('bank_res_proactive');
        if(v === 'reactive')  return this._t('bank_res_reactive');
        return this._t('bank_res_silent');
    }
}

