    window.mySimulation = new USF.SimulationFramework();
    window.mySimulation.initialize(new CPM831Adapter(), {
        simulationType: 'cpm_fasttrack_831',
        maxPeriods: 4,
        autoSaveInterval: 30000
    });
});

})();
